                    <hlm-select-item [value]="option.value">{{ option.label }}</hlm-select-item>
                  }
                </hlm-select-content>
              </hlm-select>
              @for (e of vm.recruitForm.powerClass().errors(); track e.kind) {
                <hlm-field-error>{{ e.message }}</hlm-field-error>
              }
            </div>

