import { serveStatic, launchChromium } from 'D:/Repos/angular-jig/harness/playwright/serve-and-visit.mjs';
import { resolve } from 'node:path';

const DIST = resolve('D:/Repos/angular-jig/dist/angular-jig/browser');
const srv = await serveStatic(DIST, { spaFallback: true });
const browser = await launchChromium();
const failures = [];
try {
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  page.on('pageerror', (e) => failures.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') failures.push('console: ' + m.text()); });

  // 1. Edit Silverwing's power class and power index on the detail screen.
  await page.goto(srv.origin + '/detail/HRO-0007', { waitUntil: 'networkidle' });
  await page.getByRole('tab', { name: 'Edit' }).click();
  await page.getByLabel('Power index').fill('42');
  await page.getByRole('button', { name: 'Save changes' }).click();
  await page.waitForTimeout(300);
  const notice = await page.locator('[role=status]').first().textContent();
  console.log('detail notice:', notice);

  // 2. Dashboard should show the new value in its roster table.
  await page.goto(srv.origin + '/dashboard', { waitUntil: 'networkidle' });
  const dashRow = await page.locator('tr', { hasText: 'HRO-0007' }).first().textContent();
  console.log('dashboard row after edit (in-app nav needed for shared state):', dashRow);

  // In-app navigation keeps the singleton service; use the sidebar link to prove shared state.
  await page.goto(srv.origin + '/detail/HRO-0007', { waitUntil: 'networkidle' });
  await page.getByRole('tab', { name: 'Edit' }).click();
  await page.getByLabel('Power index').fill('42');
  await page.getByRole('button', { name: 'Save changes' }).click();
  await page.waitForTimeout(200);
  await page.getByRole('link', { name: 'Dashboard' }).click();
  await page.waitForTimeout(300);
  const dash2 = await page.locator('tr', { hasText: 'HRO-0007' }).first().textContent();
  console.log('dashboard row via in-app nav:', dash2);
  await page.getByRole('link', { name: 'Roster' }).click();
  await page.waitForTimeout(300);
  const roster = await page.locator('tr', { hasText: 'HRO-0007' }).first().textContent();
  console.log('roster row via in-app nav:', roster);

  // 3. Recruit a hero and confirm the roster count rises and the detail opens.
  await page.getByRole('link', { name: 'Recruit' }).first().click();
  await page.getByLabel('Name').fill('Test Recruit');
  await page.getByLabel('Alias').fill('Trial Alias');
  await page.getByRole('button', { name: 'Recruit hero' }).click();
  await page.waitForTimeout(400);
  console.log('after recruit url:', page.url());
  await page.getByRole('link', { name: 'Roster' }).click();
  await page.waitForTimeout(300);
  console.log('roster footer:', await page.locator('[role=status]').last().textContent());

  // 4. Top-bar search opens the roster filtered.
  await page.getByRole('searchbox', { name: 'Search heroes' }).fill('Silver');
  await page.keyboard.press('Enter');
  await page.waitForTimeout(300);
  console.log('search url:', page.url(), '| footer:', await page.locator('[role=status]').last().textContent());

  // 5. Every route renders its heading.
  for (const r of ['missions', 'threats', 'settings']) {
    await page.goto(srv.origin + '/' + r, { waitUntil: 'networkidle' });
    console.log(r, 'h1:', await page.locator('h1').first().textContent());
  }
} finally {
  await browser.close();
  await srv.close?.();
}
console.log('failures:', JSON.stringify(failures, null, 1));
SCRIPT
cd "$HOME/verify-flow" && timeout 300000 node flow.mjs 2>&1 | tail -40

