import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';
import { chromium } from 'D:/Repos/angular-jig/node_modules/playwright/index.mjs';

const DIST = 'D:/Repos/angular-jig/dist/angular-jig/browser';
const TYPES = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml', '.json': 'application/json', '.ico': 'image/x-icon' };

const server = createServer(async (req, res) => {
  const path = new URL(req.url, 'http://x').pathname;
  let file = normalize(join(DIST, path));
  try {
    const body = await readFile(file);
    res.writeHead(200, { 'content-type': TYPES[extname(file)] ?? 'application/octet-stream' });
    res.end(body);
  } catch {
    const body = await readFile(join(DIST, 'index.html'));
    res.writeHead(200, { 'content-type': 'text/html' });
    res.end(body);
  }
});
await new Promise((r) => server.listen(0, '127.0.0.1', r));
const origin = `http://127.0.0.1:${server.address().port}`;

const browser = await chromium.launch();
const failures = [];
try {
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  page.on('pageerror', (e) => failures.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') failures.push('console: ' + m.text()); });

  // 1. Edit Silverwing's power index on the detail screen, save.
  await page.goto(origin + '/detail/HRO-0007', { waitUntil: 'networkidle' });
  await page.getByRole('tab', { name: 'Edit' }).click();
  await page.getByLabel('Power index').fill('42');
  await page.getByRole('button', { name: 'Save changes' }).click();
  await page.waitForTimeout(300);
  console.log('detail notice:', await page.locator('[role=status]').first().textContent());

  // 2. In-app navigation keeps the shared service: dashboard and roster must show 42.
  await page.getByRole('link', { name: 'Dashboard' }).first().click();
  await page.waitForTimeout(300);
  console.log('dashboard row after edit:', (await page.locator('tr', { hasText: 'HRO-0007' }).first().textContent())?.replace(/\s+/g, ' '));
  await page.getByRole('link', { name: 'Roster' }).first().click();
  await page.waitForTimeout(300);
  console.log('roster row after edit:', (await page.locator('tr', { hasText: 'HRO-0007' }).first().textContent())?.replace(/\s+/g, ' '));

  // 3. Power class select on the detail edit form changes the value without throwing.
  await page.getByRole('link', { name: 'Silverwing' }).first().click();
  await page.waitForTimeout(200);
  await page.getByRole('tab', { name: 'Edit' }).click();
  await page.getByRole('combobox').first().click();
  await page.getByRole('option', { name: 'Cosmic' }).click();
  await page.getByRole('button', { name: 'Save changes' }).click();
  await page.waitForTimeout(300);
  console.log('after class change, notice:', await page.locator('[role=status]').first().textContent());

  // 4. Recruit a hero; the app should open the new dossier.
  await page.getByRole('link', { name: 'Recruit' }).first().click();
  await page.waitForTimeout(200);
  await page.getByLabel('Name').fill('Test Recruit');
  await page.getByLabel('Alias').fill('Trial Alias');
  await page.getByRole('button', { name: 'Recruit hero' }).click();
  await page.waitForTimeout(400);
  console.log('after recruit url:', new URL(page.url()).pathname);
  console.log('new dossier heading:', await page.locator('h1').first().textContent());

  // 5. Top-bar search opens the roster filtered.
  await page.getByRole('link', { name: 'Roster' }).first().click();
  await page.waitForTimeout(200);
  await page.getByRole('searchbox', { name: 'Search heroes' }).fill('Silver');
  await page.keyboard.press('Enter');
  await page.waitForTimeout(400);
  console.log('search url:', new URL(page.url()).pathname + new URL(page.url()).search);
  console.log('roster footer after search:', (await page.locator('[role=status]').last().textContent())?.trim());

  // 6. Every destination renders its heading, and the placeholder text is gone.
  for (const r of ['dashboard', 'roster', 'missions', 'threats', 'recruit', 'settings']) {
    await page.goto(origin + '/' + r, { waitUntil: 'networkidle' });
    console.log(r, '->', (await page.locator('h1').first().textContent())?.trim());
  }
} finally {
  await browser.close();
  server.close();
}
console.log('failures:', JSON.stringify(failures, null, 1));

